// is being written, since NULL is also how it is cleared). Status is never set
// here, see CompleteTask/ReopenTask (tasks.proto's UpdateTask doc comment
// explains why). When expected_version is given the row must still be at that
// version; no row back means "not found" or "version mismatch" and the caller
// tells them apart.
func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (TasksTask, error) {
	row := q.db.QueryRow(ctx, updateTask,
		arg.Title,
		arg.Description,
		arg.Priority,
		arg.SetDueDate,
		arg.DueDate,
		arg.UpdatedAt,
		arg.ID,
		arg.UserID,
		arg.ExpectedVersion,
	)
	var i TasksTask
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.DueDate,
		&i.CompletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
	)
	return i, err
}
